func TestParseDurationDays(t *testing.T) {
	for in, want := range map[string]time.Duration{
		"30d": 720 * time.Hour, "1d12h": 36 * time.Hour, "1.5d": 36 * time.Hour,
		"-2d": -48 * time.Hour, "0d": 0, "1d30s": 24*time.Hour + 30*time.Second,
	} {
		if d, err := parseDuration(in); err != nil || d != want {
			t.Errorf("parseDuration(%q) = %v, %v; want %v", in, d, err, want)
		}
	}
	for _, in := range []string{"d", "1h1d", "1d-1h", "--1d", "1dd", "9999999999d", "d1h", "1d5"} {
		if d, err := parseDuration(in); err == nil {
			t.Errorf("parseDuration(%q) = %v, want error", in, d)
		}
	}
}
